#include <bits/stdc++.h>
using namespace std;

int main(){
    int n;
    if(scanf("%d",&n)!=1) return 0;
    vector<string> s(n);
    unordered_map<string,int> cnt;
    cnt.reserve(n*2);
    char buf[16];
    for(int i=0;i<n;i++){
        scanf("%s",buf);
        s[i]=buf;
        cnt[s[i]]++;
    }
    long long ans=0;
    for(int i=0;i<n;i++){
        const string &x=s[i];
        int L=(int)x.size();
        static vector<string> subs;
        subs.clear();
        subs.reserve(55);
        for(int a=0;a<L;a++)
            for(int len=1;len<=L-a;len++)
                subs.push_back(x.substr(a,len));
        sort(subs.begin(),subs.end());
        subs.erase(unique(subs.begin(),subs.end()),subs.end());
        long long c=0;
        for(auto &t:subs){
            auto it=cnt.find(t);
            if(it!=cnt.end()) c+=it->second;
        }
        c-=1; // remove o próprio par (A,A): a senha de A sempre é sub-cadeia de si mesma
        ans+=c;
    }
    printf("%lld\n",ans);
    return 0;
}
